import type { Contract } from './contract-model';
import type { Person } from './person-model';
import type { Workspace } from './workspace-model';

export const ContractDocumentStatusKeyToLabel = {
  'Current': 'Current',
  'Replaced': 'Replaced',
  'Removed': 'Removed'
} as const;
export type ContractDocumentStatusKey = keyof typeof ContractDocumentStatusKeyToLabel;

export interface ContractDocument {
  /**
   * @displayName Contract Document ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName File Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  fileName: string;
  /**
   * @displayName Content Type
   * @validationRule Required for create/update operations
   */
  contentType: string;
  /**
   * @displayName Contract
   * @validationRule Required for create/update operations
   */
  contract: Pick<Contract, 'id' | 'title'>;
  /**
   * @displayName Document Type
   * @validationRule Required for create/update operations
   */
  documentType: string;
  /**
   * @displayName File Size Bytes
   * @validationRule Required for create/update operations
   */
  fileSizeBytes: number;
  /**
   * @displayName Replacement Document
   */
  replacementDocument?: Pick<ContractDocument, 'id' | 'fileName'>;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: ContractDocumentStatusKey;
  /**
   * @displayName Storage Reference URL
   * @validationRule Required for create/update operations
   */
  storageReferenceURL: string;
  /**
   * @displayName Uploaded Date
   * @validationRule Required for create/update operations
   */
  uploadedDate: string;
  /**
   * @displayName Uploader Person
   * @validationRule Required for create/update operations
   */
  uploaderPerson: Pick<Person, 'id' | 'displayName'>;
  /**
   * @displayName Version Number
   * @validationRule Required for create/update operations
   */
  versionNumber: number;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _ContractDocument = 'ContractDocument' as const;